1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Incident = { cause: string; damages: Damage[] };
11	
12	export type QuoteStep = { op: "quote"; items: Item[] };
13	
14	// `policy` is the zero-based index of the quote step that created the policy.
15	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
16	
17	export type Step = QuoteStep | ClaimStep;
18	
19	export type Customer = { yearsWithMHPCO: number };
20	
21	export type Scenario = {
22	  customer: Customer;
23	  steps: Step[];
24	};
25	
26	export type QuoteResult = { premium: number };
27	
28	export type ClaimResult = { payout: number; remainingCap: number };
29	
30	export type StepResult = QuoteResult | ClaimResult;
31	
32	export type ScenarioResult = { results: StepResult[] };
33	
34	// The price list: one row per item type, carrying both figures the type is
35	// looked up for. `basePrice` is what the type costs to insure; `insuranceValue`
36	// is what it is insured for. The two happen to stand in a 10:1 ratio for every
37	// current row, but the specification states them independently, so they are
38	// listed independently rather than derived from one another.
39	const PRICE_LIST: Record<string, { basePrice: number; insuranceValue: number }> = {
40	  sword: { basePrice: 100, insuranceValue: 1000 },
41	  amulet: { basePrice: 60, insuranceValue: 600 },
42	  staff: { basePrice: 80, insuranceValue: 800 },
43	  potion: { basePrice: 40, insuranceValue: 400 },
44	  rune: { basePrice: 25, insuranceValue: 250 },
45	  moonstone: { basePrice: 25, insuranceValue: 250 },
46	};
47	
48	const FIRST_INSURANCE_MULTIPLIER = 1.1;
49	const CONTRACT_FEE = 5;
50	
51	const BUILDING_BLOCK_SIZE = 3;
52	const BUILDING_BLOCK_PRICE = 60;
53	
54	const CURSED_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_LEVEL = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	
58	// Each surcharge adds a percentage of the base price when its condition holds.
59	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
60	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
61	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
62	  {
63	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
64	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
65	  },
66	];
67	
68	const totalSurchargeRateFor = (item: Item): number =>
69	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
70	    (total, surcharge) => total + surcharge.rate,
71	    0,
72	  );
73	
74	// Risk surcharges apply per item, before the contract-level multiplier and fee.
75	const riskAdjustedPriceOfItem = (item: Item): number =>
76	  PRICE_LIST[item.type].basePrice * (1 + totalSurchargeRateFor(item));
77	
78	const sumOfIndividualPrices = (items: Item[]): number =>
79	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
80	
81	// "Alike" in the price list means same type — material and enchantment do not
82	// affect whether components group into a building block.
83	const groupByType = (items: Item[]): Item[][] => [
84	  ...items
85	    .reduce(
86	      (groups, item) =>
87	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
88	      new Map<string, Item[]>(),
89	    )
90	    .values(),
91	];
92	
93	// Every three alike components form a building block priced at 60 G; the
94	// remainder of the group is priced individually.
95	const priceOfAlikeGroup = (group: Item[]): number => {
96	  const completeBlocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
97	  const itemsInBlocks = completeBlocks * BUILDING_BLOCK_SIZE;
98	
99	  return (
100	    completeBlocks * BUILDING_BLOCK_PRICE +
101	    sumOfIndividualPrices(group.slice(itemsInBlocks))
102	  );
103	};
104	
105	// The basis the premium is charged on: price-list figures plus per-item risk
106	// surcharges, before any contract-level multiplier or fee. Distinct from
107	// coverSumOf, which is what those same items are insured *for*.
108	const premiumBasisOf = (items: Item[]): number =>
109	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
110	
111	const LOYALTY_YEARS = 2;
112	const LOYALTY_DISCOUNT_RATE = 0.2;
113	
114	const loyaltyMultiplierFor = (customer: Customer): number =>
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
116	
117	const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;
118	
119	// A first insurance carries an assessment surcharge; every later contract
120	// earns the repeat-customer discount instead.
121	const repeatCustomerMultiplierFor = (isFirstContract: boolean): number =>
122	  isFirstContract ? FIRST_INSURANCE_MULTIPLIER : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;
123	
124	// Customer-dependent factors that scale the whole contract, as opposed to the
125	// per-item risk surcharges already folded into the insured value.
126	const contractMultiplierFor = (
127	  customer: Customer,
128	  isFirstContract: boolean,
129	): number =>
130	  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(isFirstContract);
131	
132	// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
133	// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
134	// push an exact amount to the next whole G.
135	const roundedUpInMHPCOsFavor = (amount: number): number =>
136	  Math.ceil(Number(amount.toFixed(6)));
137	
138	const resultOfQuoteStep = (
139	  step: QuoteStep,
140	  customer: Customer,
141	  isFirstContract: boolean,
142	): QuoteResult => ({
143	  premium:
144	    roundedUpInMHPCOsFavor(
145	      premiumBasisOf(step.items) * contractMultiplierFor(customer, isFirstContract),
146	    ) + CONTRACT_FEE,
147	});
148	
149	const DEDUCTIBLE = 100;
150	const CAP_FACTOR = 2;
151	
152	// What the items are insured for, as opposed to what they cost to insure.
153	const coverSumOf = (items: Item[]): number =>
154	  items.reduce((total, item) => total + PRICE_LIST[item.type].insuranceValue, 0);
155	
156	// A claim names the quote step that created its policy. Resolving it by
157	// narrowing rather than casting means a mis-aimed index fails here, with the
158	// offending index in hand, instead of silently yielding NaN downstream.
159	const insuredItemsOf = (policyIndex: number, steps: Step[]): Item[] => {
160	  const policy = steps[policyIndex];
161	
162	  if (policy?.op !== "quote") {
163	    throw new Error(`Step ${policyIndex} is not a quote step`);
164	  }
165	
166	  return policy.items;
167	};
168	
169	const FRAGILE_ENCHANTMENT_LEVEL = 8;
170	const FRAGILE_REIMBURSEMENT_RATE = 0.5;
171	
172	const FULL_REIMBURSEMENT_RATE = 1;
173	
174	const DRAGON_MATERIAL = "dragon";
175	
176	// Order is significant: the first rule that applies sets the rate, so dragon
177	// material overrides the high-enchantment halving. Add new rules at the
178	// position matching their specificity, not at the end. Anything no rule claims
179	// is reimbursed in full.
180	const REIMBURSEMENT_RULES_MOST_SPECIFIC_FIRST: {
181	  appliesTo: (item: Item) => boolean;
182	  rate: number;
183	}[] = [
184	  {
185	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
186	    rate: FULL_REIMBURSEMENT_RATE,
187	  },
188	  {
189	    appliesTo: (item) => (item.enchantment ?? 0) >= FRAGILE_ENCHANTMENT_LEVEL,
190	    rate: FRAGILE_REIMBURSEMENT_RATE,
191	  },
192	];
193	
194	const reimbursementRateFor = (item: Item): number =>
195	  REIMBURSEMENT_RULES_MOST_SPECIFIC_FIRST.find(({ appliesTo }) => appliesTo(item))
196	    ?.rate ?? FULL_REIMBURSEMENT_RATE;
197	
198	// A damage names the type of the item it befell. A damage to something not on
199	// the policy has no insured item to rate, and is reimbursed in full.
200	const reimbursementRateForDamageTo = (
201	  itemType: string,
202	  insured: Item[],
203	): number => {
204	  const damagedItem = insured.find(({ type }) => type === itemType);
205	
206	  return damagedItem ? reimbursementRateFor(damagedItem) : FULL_REIMBURSEMENT_RATE;
207	};
208	
209	const totalReimbursableOf = (incident: Incident, insured: Item[]): number =>
210	  incident.damages.reduce(
211	    (total, { itemType, amount }) =>
212	      total + amount * reimbursementRateForDamageTo(itemType, insured),
213	    0,
214	  );
215	
216	// The customer bears the deductible, and never the other way round: a damage
217	// smaller than the deductible pays nothing rather than billing the customer.
218	const afterDeductible = (reimbursable: number): number =>
219	  Math.max(0, reimbursable - DEDUCTIBLE);
220	
221	const payoutCapOf = (insured: Item[]): number =>
222	  CAP_FACTOR * coverSumOf(insured);
223	
224	// The cap belongs to the policy, not the claim: successive claims draw down a
225	// shared balance, so the caller supplies what earlier claims have left.
226	const resultOfClaimStep = (
227	  step: ClaimStep,
228	  steps: Step[],
229	  capRemaining: number,
230	): ClaimResult => {
231	  const insured = insuredItemsOf(step.policy, steps);
232	  // The cap is the ceiling on what a policy pays, not on what it reimburses,
233	  // so it is applied last — outermost here, after the deductible is borne.
234	  const payout = Math.min(
235	    capRemaining,
236	    afterDeductible(totalReimbursableOf(step.incident, insured)),
237	  );
238	
239	  return { payout, remainingCap: capRemaining - payout };
240	};
241	
242	// It is contracts that count, not steps: a quote preceded only by claim steps
243	// is still the customer's first contract. Claims are therefore not counted.
244	const isFirstContractAt = (stepIndex: number, steps: Step[]): boolean =>
245	  !steps.slice(0, stepIndex).some(({ op }) => op === "quote");
246	
247	// What running the scenario carries from one step to the next: the results so
248	// far, and how much of each policy's cap its earlier claims have left. A policy
249	// absent from the ledger has not been claimed against yet and still has its
250	// full cap; policies draw down independently of one another.
251	type ScenarioProgress = {
252	  results: StepResult[];
253	  capRemainingByPolicy: Map<number, number>;
254	};
255	
256	const EMPTY_PROGRESS: ScenarioProgress = {
257	  results: [],
258	  capRemainingByPolicy: new Map(),
259	};
260	
261	const withResult = (
262	  progress: ScenarioProgress,
263	  result: StepResult,
264	): ScenarioProgress => ({
265	  ...progress,
266	  results: [...progress.results, result],
267	});
268	
269	// A quote leaves the ledger untouched: caps are drawn down by claims alone.
270	const progressAfterQuoteStep = (
271	  step: QuoteStep,
272	  index: number,
273	  scenario: Scenario,
274	  progress: ScenarioProgress,
275	): ScenarioProgress =>
276	  withResult(
277	    progress,
278	    resultOfQuoteStep(
279	      step,
280	      scenario.customer,
281	      isFirstContractAt(index, scenario.steps),
282	    ),
283	  );
284	
285	// The ledger's own rule for what a policy has left: an entry once it has been
286	// claimed against, and otherwise the full cap it was written with.
287	const capRemainingForPolicy = (
288	  policyIndex: number,
289	  steps: Step[],
290	  progress: ScenarioProgress,
291	): number =>
292	  progress.capRemainingByPolicy.get(policyIndex) ??
293	  payoutCapOf(insuredItemsOf(policyIndex, steps));
294	
295	const withCapRemainingForPolicy = (
296	  progress: ScenarioProgress,
297	  policyIndex: number,
298	  capRemaining: number,
299	): ScenarioProgress => ({
300	  ...progress,
301	  capRemainingByPolicy: new Map(progress.capRemainingByPolicy).set(
302	    policyIndex,
303	    capRemaining,
304	  ),
305	});
306	
307	// A claim is the only step that both reads and advances the ledger, so it is
308	// the only one that returns a new one.
309	const progressAfterClaimStep = (
310	  step: ClaimStep,
311	  steps: Step[],
312	  progress: ScenarioProgress,
313	): ScenarioProgress => {
314	  const result = resultOfClaimStep(
315	    step,
316	    steps,
317	    capRemainingForPolicy(step.policy, steps, progress),
318	  );
319	
320	  return withResult(
321	    withCapRemainingForPolicy(progress, step.policy, result.remainingCap),
322	    result,
323	  );
324	};
325	
326	// Steps are folded rather than mapped: a claim's payout depends on what earlier
327	// claims on the same policy have already drawn, so the steps are not
328	// independent and the carried ledger belongs in the signature, not in a closure.
329	export const runScenario = (scenario: Scenario): ScenarioResult => {
330	  const { results } = scenario.steps.reduce<ScenarioProgress>(
331	    (progress, step, index) =>
332	      step.op === "quote"
333	        ? progressAfterQuoteStep(step, index, scenario, progress)
334	        : progressAfterClaimStep(step, scenario.steps, progress),
335	    EMPTY_PROGRESS,
336	  );
337	
338	  return { results };
339	};
