// "Alike" in the price list means same type — material and enchantment do not
// affect whether components group into a building block.
const groupByType = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

// Every three alike components form a building block priced at 60 G; the
// remainder of the group is priced individually.
const priceOfAlikeGroup = (group: Item[]): number => {
  const completeBlocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
  const itemsInBlocks = completeBlocks * BUILDING_BLOCK_SIZE;

  return (
    completeBlocks * BUILDING_BLOCK_PRICE +
    sumOfIndividualPrices(group.slice(itemsInBlocks))
  );
};

